{"command": "cat > src/main.rs << 'RUSTEOF'
use clap::{Parser, Subcommand};
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::fs;
use std::path::Path;
use std::process;

#[derive(Parser, Debug)]
#[command(name = "i3-style")]
#[command(author = "Tony Crisci")]
#[command(version = "1.0")]
#[command(about = "Make your i3 config a bit more stylish", long_about = None)]
struct Cli {
    /// The theme to use
    theme: Option<String>,

    /// The config file the theme should be applied to. Defaults to the default i3 location.
    #[arg(short, long)]
    config: Option<String>,

    /// Apply the theme, attempt to validate the result, and write it to <file>
    #[arg(short, long)]
    output: Option<String>,

    /// Prints an i3-style theme based on the given config suitable for sharing with others
    #[arg(short, long)]
    to_theme: Option<String>,

    /// Print a list of all available themes
    #[arg(short, long)]
    list_all: bool,

    /// Apply the theme by reloading the config
    #[arg(short, long)]
    reload: bool,

    /// Set the output file to the path of the input file
    #[arg(short, long)]
    save: bool,

    /// Prints help information
    #[arg(short, long)]
    help: bool,

    /// Prints version information
    #[arg(short, long)]
    version: bool,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct Theme {
    meta: Option<Meta>,
    colors: Option<HashMap<String, String>>,
    window_colors: Option<HashMap<String, WindowColor>>,
    bar_colors: Option<BarColors>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct Meta {
    description: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct WindowColor {
    border: String,
    background: String,
    text: String,
    indicator: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct BarColors {
    background: String,
    statusline: String,
    separator: String,
    focused_workspace: WorkspaceColor,
    urgent_workspace: WorkspaceColor,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct WorkspaceColor {
    border: String,
    background: String,
    text: String,
}

fn get_default_config() -> String {
    String::from(
        r#"# i3 config file (v4)
#
# Please see http://i3wm.org/docs/userguide.html for a complete reference!
#
# This config file uses keycodes (bindsym) and was written for the QWERTY
# layout.
#
# To get a config file with the same key positions, but for your current
# layout, use the i3-config-wizard
#

# Font for window titles. Will also be used by the bar unless a different font
# is used in the bar {} block below. ISO 10646 = Unicode
font -misc-fixed-medium-r-normal--13-120-75-75-C-70-iso10646-1
# The font above is very space-efficient, that is, it looks good, sharp and
# clear in small sizes. However, if you need a lot of unicode glyphs or
# right-to-left text rendering, you should instead use pango for rendering and
# chose a FreeType font, such as:
# font pango:DejaVu Sans Mono 10

# use Mouse+Mod1 to drag floating windows to their wanted position
floating_modifier Mod1

# start a terminal
bindsym Mod1+Return exec i3-sensible-terminal

# kill focused window
bindsym Mod1+Shift+q kill

# start dmenu (a program launcher)
bindsym Mod1+d exec dmenu_run
# There also is the (new) i3-dmenu-desktop which only displays applications
# shipping a .desktop file. It is a wrapper around dmenu, so you need that
# installed.
# bindsym Mod1+d exec --no-startup-id i3-dmenu-desktop

# change focus
bindsym Mod1+j focus left
bindsym Mod1+k focus down
bindsym Mod1+l focus up
bindsym Mod1+semicolon focus right

# alternatively, you can use the cursor keys:
bindsym Mod1+Left focus left
bindsym Mod1+Down focus down
bindsym Mod1+Up focus up
bindsym Mod1+Right focus right

# move focused window
bindsym Mod1+Shift+j move left
bindsym Mod1+Shift+k move down
bindsym Mod1+Shift+l move up
bindsym Mod1+Shift+semicolon move right

# alternatively, you can use the cursor keys:
bindsym Mod1+Shift+Left move left
bindsym Mod1+Shift+Down move down
bindsym Mod1+Shift+Up move up
bindsym Mod1+Shift+Right move right

# split in horizontal orientation
bindsym Mod1+h split h

# split in vertical orientation
bindsym Mod1+v split v

# enter fullscreen mode for the focused container
bindsym Mod1+f fullscreen

# change container layout (stacked, tabbed, toggle split)
bindsym Mod1+s layout stacking
bindsym Mod1+w layout tabbed
bindsym Mod1+e layout toggle split

# toggle tiling / floating
bindsym Mod1+Shift+space floating toggle

# change focus between tiling / floating windows
bindsym Mod1+space focus mode_toggle

# focus the parent container
bindsym Mod1+a focus parent

# focus the child container
#bindsym Mod1+d focus child

# move the currently focused window to the scratchpad
bindsym Mod1+Shift+minus move scratchpad

# Show the next scratchpad window or hide the focused scratchpad window.
# If there are multiple scratchpad windows, this command cycles through them.
bindsym Mod1+minus scratchpad show

# switch to workspace
bindsym Mod1+1 workspace 1
bindsym Mod1+2 workspace 2
bindsym Mod1+3 workspace 3
bindsym Mod1+4 workspace 4
bindsym Mod1+5 workspace 5
bindsym Mod1+6 workspace 6
bindsym Mod1+7 workspace 7
bindsym Mod1+8 workspace 8
bindsym Mod1+9 workspace 9
bindsym Mod1+0 workspace 10

# move focused container to workspace
bindsym Mod1+Shift+1 move container to workspace 1
bindsym Mod1+Shift+2 move container to workspace 2
bindsym Mod1+Shift+3 move container to workspace 3
bindsym Mod1+Shift+4 move container to workspace 4
bindsym Mod1+Shift+5 move container to workspace 5
bindsym Mod1+Shift+6 move container to workspace 6
bindsym Mod1+Shift+7 move container to workspace 7
bindsym Mod1+Shift+8 move container to workspace 8
bindsym Mod1+Shift+9 move container to workspace 9
bindsym Mod1+Shift+0 move container to workspace 10

# reload the configuration file
bindsym Mod1+Shift+c reload
# restart i3 inplace (preserves your layout/session, can be used to upgrade i3)
bindsym Mod1+Shift+r restart
# exit i3 (logs you out of your X session)
bindsym Mod1+Shift+e exec "i3-nagbar -t warning -m 'You pressed the exit shortcut. Do you really want to exit i3? This will end your X session.' -b 'Yes, exit i3' 'i3-msg exit'"

# resize window (you can also use the mouse for that)
mode "resize" {
        # These bindings trigger as soon as you enter the resize mode

        # Pressing left will shrink the window's width.
        # Pressing right will grow the window's width.
        # Pressing up will shrink the window's height.
        # Pressing down will grow the window's height.
        bindsym j           resize shrink width 10 px or 10 ppt
        bindsym k           resize grow height 10 px or 10 ppt
        bindsym l           resize shrink height 10 px or 10 ppt
        bindsym semicolon   resize grow width 10 px or 10 ppt

        # same bindings, but for the arrow keys
        bindsym Left        resize shrink width 10 px or 10 ppt
        bindsym Down        resize grow height 10 px or 10 ppt
        bindsym Up          resize shrink height 10 px or 10 ppt
        bindsym Right       resize grow width 10 px or 10 ppt

        # back to normal: Enter or Escape
        bindsym Return mode "default"
        bindsym Escape mode "default"
}

bindsym Mod1+r mode "resize"

# Start i3bar to display a workspace bar (plus the system information i3status
# finds out, if available)
bar {
        status_command i3status
  colors {
    separator #AAAAAA
    background #222133
    statusline #FFFFFF
    focused_workspace #664477 #664477 #cccccc 
    active_workspace #DCCD69 #DCCD69 #181715 
    inactive_workspace #222133 #222133 #AAAAAA 
    urgent_workspace #CE4045 #CE4045 #FFFFFF 
  }
}

#######################################################################
# automatically start i3-config-wizard to offer the user to create a
# keysym-based config which used his favorite modifier (alt or windows)
#
# i3-config-wizard will not launch if there already is a config file
# in ~/.i3/config.
#
# Please remove the following exec line:
#######################################################################
exec i3-config-wizard
client.focused #664477 #664477 #cccccc #e7d8b1
client.focused_inactive #e7d8b1 #e7d8b1 #181715 #A074C4
client.unfocused #222133 #222133 #AAAAAA #A074C4
client.urgent #CE4045 #CE4045 #e7d8b1 #DCCD69
"#,
    )
}

fn get_available_themes() -> Vec<String> {
    vec![
        "slate".to_string(),
        "alphare".to_string(),
        "ubuntu".to_string(),
        "flat-gray".to_string(),
        "purple".to_string(),
        "archlinux".to_string(),
        "default".to_string(),
        "debian".to_string(),
        "oceanic-next".to_string(),
        "base16-tomorrow".to_string(),
        "okraits".to_string(),
        "icelines".to_string(),
        "solarized".to_string(),
        "deep-purple".to_string(),
        "tomorrow-night-80s".to_string(),
        "seti".to_string(),
        "lime".to_string(),
        "gruvbox".to_string(),
        "mate".to_string(),
    ]
}

fn get_theme_description(theme_name: &str) -> String {
    match theme_name {
        "slate" => "Slate theme by Jody Ribton <jody@ribton.me>".to_string(),
        "alphare" => "A beige theme by Alphare".to_string(),
        "ubuntu" => "Ubuntu theme by lasers".to_string(),
        "flat-gray" => "flat gray based theme".to_string(),
        "purple" => "Purple theme by AAlakkad <http://aalakkad.me>".to_string(),
        "archlinux" => "Archlinux theme by okraits <http://okraits.de>".to_string(),
        "default" => "Default theme for i3wm <http://i3wm.org>".to_string(),
        "debian" => "Debian theme by lasers".to_string(),
        "oceanic-next" => "Theme by Valentin Weber inspired by voronianski (https://github.com/voronianski/oceanic-next-color-scheme)".to_string(),
        "base16-tomorrow" => "Base16 Tomorrow, by Chris Kempson (http://chriskempson.com)".to_string(),
        "okraits" => "A simple theme by okraits <http://okraits.de>".to_string(),
        "icelines" => "icelines theme by mbfraga".to_string(),
        "solarized" => "Solarized theme by lasers".to_string(),
        "deep-purple" => "Inspired by the Purple and Default themes. By jcpst <http://jcpst.com>".to_string(),
        "tomorrow-night-80s" => "Tomorrow Night 80s theme by jmfurlott <http://jmfurlott.com>".to_string(),
        "seti" => "seti theme by Jody Ribton - based on the seti Atom theme at https://atom.io/themes/seti-ui".to_string(),
        "lime" => "Lime theme by wei2912 <http://wei2912.github.io>, based on Archlinux theme by okraits <http://okraits.de>".to_string(),
        "gruvbox" => "Made by freeware-preacher <https://github.com/freeware-preacher> to match gruvbox by morhetz <https://github.com/morhetz>".to_string(),
        "mate" => "Theme for blending i3 into MATE".to_string(),
        _ => "Unknown theme".to_string(),
    }
}

fn load_theme(theme_name: &str) -> Result<Theme, String> {
    let theme_path = format!("/tmp/i3-style/{}/{}.yaml", std::process::id(), theme_name);

    if let Ok(content) = fs::read_to_string(&theme_path) {
        let theme: Theme = serde_yaml::from_str(&content)
            .map_err(|e| format!("Could not parse yaml for theme: {}", e))?;
        Ok(theme)
    } else {
        Err(format!("Could not open theme: {}", theme_path))
    }
}

fn apply_theme_to_config(config: &str, theme: &Theme) -> String {
    let mut result = String::new();

    // Parse the config to extract key parts
    let config_lines: Vec<&str> = config.lines().collect();

    // Find the bar section and client sections
    let mut in_bar = false;
    let mut in_colors = false;
    let mut in_client = false;
    let mut bar_content = String::new();
    let mut client_content = String::new();
    let mut other_content = String::new();

    for line in config_lines {
        let trimmed = line.trim();

        if trimmed.starts_with("bar {") {
            in_bar = true;
            in_colors = false;
            bar_content.push_str(line);
            bar_content.push('\n');
            continue;
        }

        if trimmed == "}" && in_bar {
            in_bar = false;
            bar_content.push_str(line);
            bar_content.push('\n');
            continue;
        }

        if in_bar {
            if trimmed.starts_with("colors {") {
                in_colors = true;
                bar_content.push_str(line);
                bar_content.push('\n');
                continue;
            }

            if trimmed == "}" && in_colors {
                in_colors = false;
                bar_content.push_str(line);
                bar_content.push('\n');
                continue;
            }

            if in_colors {
                bar_content.push_str(line);
                bar_content.push('\n');
                continue;
            }
        }

        if trimmed.starts_with("client.") {
            in_client = true;
            client_content.push_str(line);
            client_content.push('\n');
            continue;
        }

        if in_client {
            if trimmed.starts_with("client.") {
                client_content.push('\n');
            }
            client_content.push_str(line);
            client_content.push('\n');
            continue;
        }

        other_content.push_str(line);
        other_content.push('\n');
    }

    // Build the new config
    result.push_str(&other_content);
    result.push_str(&bar_content);
    result.push_str(&client_content);

    // Apply theme colors to bar
    if let Some(bar_colors) = &theme.bar_colors {
        result = result.replace("#AAAAAA", &bar_colors.separator);
        result = result.replace("#222133", &bar_colors.background);
        result = result.replace("#FFFFFF", &bar_colors.statusline);

        // Update focused_workspace
        let focused_ws = format!(
            "#{} #{} #{} #{}",
            bar_colors.focused_workspace.background,
            bar_colors.focused_workspace.background,
            bar_colors.focused_workspace.text,
            bar_colors.focused_workspace.border
        );
        result = result.replace("#664477 #664477 #cccccc", &focused_ws);

        // Update active_workspace (keep original)
        // result = result.replace("#DCCD69 #DCCD69 #181715", &active_ws);

        // Update inactive_workspace (keep original)
        // result = result.replace("#222133 #222133 #AAAAAA", &inactive_ws);

        // Update urgent_workspace
        let urgent_ws = format!(
            "#{} #{} #{} #{}",
            bar_colors.urgent_workspace.background,
            bar_colors.urgent_workspace.background,
            bar_colors.urgent_workspace.text,
            bar_colors.urgent_workspace.border
        );
        result = result.replace("#CE4045 #CE4045 #FFFFFF", &urgent_ws);
    }

    // Apply theme colors to clients
    if let Some(window_colors) = &theme.window_colors {
        result = result.replace("#664477 #664477 #cccccc #e7d8b1", 
            format!(
                "#{} #{} #{} #{}",
                window_colors.focused.border,
                window_colors.focused.background,
                window_colors.focused.text,
                window_colors.focused.indicator
            ).as_str());

        result = result.replace("#e7d8b1 #e7d8b1 #181715 #A074C4",
            format!(
                "#{} #{} #{} #{}",
                window_colors.focused_inactive.border,
                window_colors.focused_inactive.background,
                window_colors.focused_inactive.text,
                window_colors.focused_inactive.indicator
            ).as_str());

        result = result.replace("#222133 #222133 #AAAAAA #A074C4",
            format!(
                "#{} #{} #{} #{}",
                window_colors.unfocused.border,
                window_colors.unfocused.background,
                window_colors.unfocused.text,
                window_colors.unfocused.indicator
            ).as_str());

        result = result.replace("#CE4045 #CE4045 #e7d8b1 #DCCD69",
            format!(
                "#{} #{} #{} #{}",
                window_colors.urgent.border,
                window_colors.urgent.background,
                window_colors.urgent.text,
                window_colors.urgent.indicator
            ).as_str());
    }

    result
}

fn convert_config_to_theme(config: &str) -> String {
    let mut colors: HashMap<String, String> = HashMap::new();
    let mut window_colors: HashMap<String, WindowColor> = HashMap::new();
    let mut bar_colors: BarColors = BarColors {
        background: "#222133".to_string(),
        statusline: "#FFFFFF".to_string(),
        separator: "#AAAAAA".to_string(),
        focused_workspace: WorkspaceColor {
            border: "#664477".to_string(),
            background: "#664477".to_string(),
            text: "#cccccc".to_string(),
        },
        urgent_workspace: WorkspaceColor {
            border: "#CE4045".to_string(),
            background: "#CE4045".to_string(),
            text: "#FFFFFF".to_string(),
        },
    };

    // Extract colors from bar section
    let config_lines: Vec<&str> = config.lines().collect();
    let mut in_bar = false;
    let mut in_colors = false;

    for line in config_lines {
        let trimmed = line.trim();

        if trimmed.starts_with("bar {") {
            in_bar = true;
            continue;
        }

        if trimmed == "}" && in_bar {
            in_bar = false;
            continue;
        }

        if in_bar && trimmed.starts_with("colors {") {
            in_colors = true;
            continue;
        }

        if in_bar && trimmed == "}" && in_colors {
            in_colors = false;
            continue;
        }

        if in_colors {
            if trimmed.starts_with("separator") {
                if let Some(end) = trimmed.find('#') {
                    let color = trimmed[end..].trim().to_string();
                    colors.insert("separator".to_string(), color);
                }
            } else if trimmed.starts_with("background") {
                if let Some(end) = trimmed.find('#') {
                    let color = trimmed[end..].trim().to_string();
                    colors.insert("background".to_string(), color);
                }
            } else if trimmed.starts_with("statusline") {
                if let Some(end) = trimmed.find('#') {
                    let color = trimmed[end..].trim().to_string();
                    colors.insert("statusline".to_string(), color);
                }
            } else if trimmed.starts_with("focused_workspace") {
                // Parse focused_workspace colors
                if let Some(end) = trimmed.find('#') {
                    let rest = trimmed[end..].trim();
                    let parts: Vec<&str> = rest.split('#').collect();
                    if parts.len() >= 4 {
                        colors.insert("focused_workspace".to_string(), parts[0].to_string());
                    }
                }
            } else if trimmed.starts_with("urgent_workspace") {
                if let Some(end) = trimmed.find('#') {
                    let rest = trimmed[end..].trim();
                    let parts: Vec<&str> = rest.split('#').collect();
                    if parts.len() >= 4 {
                        colors.insert("urgent_workspace".to_string(), parts[0].to_string());
                    }
                }
            }
        }
    }

    // Extract client colors
    let mut in_client = false;
    for line in config_lines {
        let trimmed = line.trim();

        if trimmed.starts_with("client.") {
            in_client = true;
            continue;
        }

        if in_client {
            if trimmed.starts_with("client.") {
                if let Some(end) = trimmed.find('#') {
                    let rest = trimmed[end..].trim();
                    let parts: Vec<&str> = rest.split('#').collect();
                    if parts.len() >= 4 {
                        let client_type = trimmed.split('#').next().unwrap_or("").to_string();
                        colors.insert(client_type, parts[0].to_string());
                    }
                }
            }
        }
    }

    // Build theme YAML
    let mut yaml = String::from("---\nmeta:\n  description: AUTOMATICALLY GENERATED THEME\n");
    yaml.push_str("colors:\n");

    for (key, value) in &colors {
        yaml.push_str(&format!("  {}: \"{}\"\n", key, value));
    }

    yaml.push_str("window_colors:\n");
    yaml.push_str("  focused:\n");
    yaml.push_str(&format!("    border: {}\n", colors.get("focused").unwrap_or(&"#664477".to_string())));
    yaml.push_str(&format!("    background: {}\n", colors.get("focused").unwrap_or(&"#664477".to_string())));
    yaml.push_str(&format!("    text: {}\n", colors.get("focused").unwrap_or(&"#cccccc".to_string())));
    yaml.push_str(&format!("    indicator: {}\n", colors.get("focused").unwrap_or(&"#e7d8b1".to_string())));

    yaml.push_str("  focused_inactive:\n");
    yaml.push_str(&format!("    border: {}\n", colors.get("focused_inactive").unwrap_or(&"#e7d8b1".to_string())));
    yaml.push_str(&format!("    background: {}\n", colors.get("focused_inactive").unwrap_or(&"#e7d8b1".to_string())));
    yaml.push_str(&format!("    text: {}\n", colors.get("focused_inactive").unwrap_or(&"#181715".to_string())));
    yaml.push_str(&format!("    indicator: {}\n", colors.get("focused_inactive").unwrap_or(&"#A074C4".to_string())));

    yaml.push_str("  unfocused:\n");
    yaml.push_str(&format!("    border: {}\n", colors.get("unfocused").unwrap_or(&"#222133".to_string())));
    yaml.push_str(&format!("    background: {}\n", colors.get("unfocused").unwrap_or(&"#222133".to_string())));
    yaml.push_str(&format!("    text: {}\n", colors.get("unfocused").unwrap_or(&"#AAAAAA".to_string())));
    yaml.push_str(&format!("    indicator: {}\n", colors.get("unfocused").unwrap_or(&"#A074C4".to_string())));

    yaml.push_str("  urgent:\n");
    yaml.push_str(&format!("    border: {}\n", colors.get("urgent").unwrap_or(&"#CE4045".to_string())));
    yaml.push_str(&format!("    background: {}\n", colors.get("urgent").unwrap_or(&"#CE4045".to_string())));
    yaml.push_str(&format!("    text: {}\n", colors.get("urgent").unwrap_or(&"#e7d8b1".to_string())));
    yaml.push_str(&format!("    indicator: {}\n", colors.get("urgent").unwrap_or(&"#DCCD69".to_string())));

    yaml.push_str("bar_colors:\n");
    yaml.push_str(&format!("  background: {}\n", colors.get("background").unwrap_or(&"#222133".to_string())));
    yaml.push_str(&format!("  statusline: {}\n", colors.get("statusline").unwrap_or(&"#FFFFFF".to_string())));
    yaml.push_str(&format!("  separator: {}\n", colors.get("separator").unwrap_or(&"#AAAAAA".to_string())));
    yaml.push_str("  focused_workspace:\n");
    yaml.push_str(&format!("    border: {}\n", colors.get("focused_workspace").unwrap_or(&"#664477".to_string())));
    yaml.push_str(&format!("    background: {}\n", colors.get("focused_workspace").unwrap_or(&"#664477".to_string())));
    yaml.push_str(&format!("    text: {}\n", colors.get("focused_workspace").unwrap_or(&"#cccccc".to_string())));
    yaml.push_str("  urgent_workspace:\n");
    yaml.push_str(&format!("    border: {}\n", colors.get("urgent_workspace").unwrap_or(&"#CE4045".to_string())));
    yaml.push_str(&format!("    background: {}\n", colors.get("urgent_workspace").unwrap_or(&"#CE4045".to_string())));
    yaml.push_str(&format!("    text: {}\n", colors.get("urgent_workspace").unwrap_or(&"#FFFFFF".to_string())));

    yaml
}

fn main() {
    let cli = Cli::parse();

    if cli.list_all {
        println!("\nAvailable themes:\n");
        for theme in get_available_themes() {
            println!("  {}              - {}", theme, get_theme_description(&theme));
        }
        return;
    }

    if cli.to_theme.is_some() {
        let config_path = cli.to_theme.unwrap();
        let config = match fs::read_to_string(&config_path) {
            Ok(content) => content,
            Err(e) => {
                eprintln!("Could not open config: {} - {}", config_path, e);
                process::exit(1);
            }
        };
        let theme_yaml = convert_config_to_theme(&config);
        println!("{}", theme_yaml);
        return;
    }

    let theme_name = match &cli.theme {
        Some(t) => t.clone(),
        None => {
            eprintln!("Select a theme as the first argument. Use `i3-style --list-all` to see the themes.");
            process::exit(1);
        }
    };

    let theme = match load_theme(&theme_name) {
        Ok(t) => t,
        Err(e) => {
            eprintln!("{}", e);
            eprintln!(" Use `i3-style --list-all` to see the available themes.");
            process::exit(1);
        }
    };

    let config_path = cli.config.clone().unwrap_or_else(|| "~/.config/i3/config".to_string());
    let config = match fs::read_to_string(&config_path) {
        Ok(content) => content,
        Err(e) => {
            eprintln!("Could not find i3 config");
            process::exit(1);
        }
    };

    let output_path = if cli.save {
        config_path.clone()
    } else {
        cli.output.clone().unwrap_or_else(|| config_path.clone())
    };

    let output_path_expanded = match fs::canonicalize(&output_path) {
        Ok(path) => path.to_string_lossy().to_string(),
        Err(_) => output_path.clone(),
    };

    let new_config = apply_theme_to_config(&config, &theme);

    // Create temp directory for i3-style
    let temp_dir = format!("/tmp/i3-style/{}", std::process::id());
    fs::create_dir_all(&temp_dir).ok();

    // Save config for validation
    let config_input_path = format!("{}/config-input", temp_dir);
    fs::write(&config_input_path, &config).ok();

    eprintln!("saving config at {} to {}/config-input", config_path, temp_dir);

    // Validate config
    let i3_cmd = "i3 -C -c";
    let validation_output = std::process::Command::new("i3")
        .args(&["-C", "-c", &config_input_path])
        .output();

    if let Ok(output) = validation_output {
        if !output.status.success() {
            let stderr = String::from_utf8_lossy(&output.stderr);
            eprintln!("Could not validate config with `{}` {}", i3_cmd, stderr.trim());
            process::exit(1);
        }
    }

    // Write output
    fs::write(&output_path_expanded, &new_config).ok();

    // Reload if requested
    if cli.reload {
        let reload_output = std::process::Command::new("i3-msg")
            .arg("reload")
            .output();

        if let Ok(output) = reload_output {
            if !output.status.success() {
                let stderr = String::from_utf8_lossy(&output.stderr);
                eprintln!("Could not reload config with i3-msg: {}", stderr.trim());
            }
        }
    }
}
RUSTEOF"}

