fn apply_theme_to_config(config: &str, theme: &Theme) -> String {
    let mut result = String::new();

    // Parse the config to extract key parts
    let config_lines: Vec<&str> = config.lines().collect();

    // Find the bar section and client sections
    let mut in_bar = false;
    let mut in_colors = false;
    let mut in_client = false;
    let mut bar_content = String::new();
    let mut client_content = String::new();
    let mut other_content = String::new();

    for line in config_lines {
        let trimmed = line.trim();

        if trimmed.starts_with("bar {") {
            in_bar = true;
            in_colors = false;
            bar_content.push_str(line);
            bar_content.push('\n');
            continue;
        }

        if trimmed == "}" && in_bar {
            in_bar = false;
            bar_content.push_str(line);
            bar_content.push('\n');
            continue;
        }

        if in_bar {
            if trimmed.starts_with("colors {") {
                in_colors = true;
                bar_content.push_str(line);
                bar_content.push('\n');
                continue;
            }

            if trimmed == "}" && in_colors {
                in_colors = false;
                bar_content.push_str(line);
                bar_content.push('\n');
                continue;
            }

            if in_colors {
                bar_content.push_str(line);
                bar_content.push('\n');
                continue;
            }
        }

        if trimmed.starts_with("client.") {
            in_client = true;
            client_content.push_str(line);
            client_content.push('\n');
            continue;
        }

        if in_client {
            if trimmed.starts_with("client.") {
                client_content.push('\n');
            }
            client_content.push_str(line);
            client_content.push('\n');
            continue;
        }

        other_content.push_str(line);
        other_content.push('\n');
    }

    // Build the new config
    result.push_str(&other_content);
    result.push_str(&bar_content);
    result.push_str(&client_content);

    // Apply theme colors to bar
    if let Some(bar_colors) = &theme.bar_colors {
        result = result.replace("#AAAAAA", &bar_colors.separator);
        result = result.replace("#222133", &bar_colors.background);
        result = result.replace("#FFFFFF", &bar_colors.statusline);

        // Update focused_workspace
        let focused_ws = format!(
            "#{} #{} #{} #{}",
            bar_colors.focused_workspace.background,
            bar_colors.focused_workspace.background,
            bar_colors.focused_workspace.text,
            bar_colors.focused_workspace.border
        );
        result = result.replace("#664477 #664477 #cccccc", &focused_ws);

        // Update active_workspace (keep original)
        // result = result.replace("#DCCD69 #DCCD69 #181715", &active_ws);

        // Update inactive_workspace (keep original)
        // result = result.replace("#222133 #222133 #AAAAAA", &inactive_ws);

        // Update urgent_workspace
        let urgent_ws = format!(
            "#{} #{} #{} #{}",
            bar_colors.urgent_workspace.background,
            bar_colors.urgent_workspace.background,
            bar_colors.urgent_workspace.text,
            bar_colors.urgent_workspace.border
        );
        result = result.replace("#CE4045 #CE4045 #FFFFFF", &urgent_ws);
    }

    // Apply theme colors to clients
    if let Some(window_colors) = &theme.window_colors {
        result = result.replace("#664477 #664477 #cccccc #e7d8b1", 
            format!(
                "#{} #{} #{} #{}",
                window_colors.focused.border,
                window_colors.focused.background,
                window_colors.focused.text,
                window_colors.focused.indicator
            ).as_str());

        result = result.replace("#e7d8b1 #e7d8b1 #181715 #A074C4",
            format!(
                "#{} #{} #{} #{}",
                window_colors.focused_inactive.border,
                window_colors.focused_inactive.background,
                window_colors.focused_inactive.text,
                window_colors.focused_inactive.indicator
            ).as_str());

        result = result.replace("#222133 #222133 #AAAAAA #A074C4",
            format!(
                "#{} #{} #{} #{}",
                window_colors.unfocused.border,
                window_colors.unfocused.background,
                window_colors.unfocused.text,
                window_colors.unfocused.indicator
            ).as_str());

        result = result.replace("#CE4045 #CE4045 #e7d8b1 #DCCD69",
            format!(
                "#{} #{} #{} #{}",
                window_colors.urgent.border,
                window_colors.urgent.background,
                window_colors.urgent.text,
                window_colors.urgent.indicator
            ).as_str());
    }

    result
}

fn convert_config_to_theme(config: &str) -> String {
    let mut colors: HashMap<String, String> = HashMap::new();
    let mut window_colors: HashMap<String, WindowColor> = HashMap::new();
    let mut bar_colors: BarColors = BarColors {
        background: "#222133".to_string(),
        statusline: "#FFFFFF".to_string(),
        separator: "#AAAAAA".to_string(),
        focused_workspace: WorkspaceColor {
            border: "#664477".to_string(),
            background: "#664477".to_string(),
            text: "#cccccc".to_string(),
        },
        urgent_workspace: WorkspaceColor {
            border: "#CE4045".to_string(),
            background: "#CE4045".to_string(),
            text: "#FFFFFF".to_string(),
        },
    };

    // Extract colors from bar section
    let config_lines: Vec<&str> = config.lines().collect();
    let mut in_bar = false;
    let mut in_colors = false;

    for line in config_lines {
        let trimmed = line.trim();

        if trimmed.starts_with("bar {") {
            in_bar = true;
            continue;
        }

        if trimmed == "}" && in_bar {
            in_bar = false;
            continue;
        }

        if in_bar && trimmed.starts_with("colors {") {
            in_colors = true;
            continue;
        }

        if in_bar && trimmed == "}" && in_colors {
            in_colors = false;
            continue;
        }

        if in_colors {
            if trimmed.starts_with("separator") {
                if let Some(end) = trimmed.find('#') {
                    let color = trimmed[end..].trim().to_string();
                    colors.insert("separator".to_string(), color);
                }
            } else if trimmed.starts_with("background") {
                if let Some(end) = trimmed.find('#') {
                    let color = trimmed[end..].trim().to_string();
                    colors.insert("background".to_string(), color);
                }
            } else if trimmed.starts_with("statusline") {
                if let Some(end) = trimmed.find('#') {
                    let color = trimmed[end..].trim().to_string();
                    colors.insert("statusline".to_string(), color);
                }
            } else if trimmed.starts_with("focused_workspace") {
                // Parse focused_workspace colors
                if let Some(end) = trimmed.find('#') {
                    let rest = trimmed[end..].trim();
                    let parts: Vec<&str> = rest.split('#').collect();
                    if parts.len() >= 4 {
                        colors.insert("focused_workspace".to_string(), parts[0].to_string());
                    }
                }
            } else if trimmed.starts_with("urgent_workspace") {
                if let Some(end) = trimmed.find('#') {
                    let rest = trimmed[end..].trim();
                    let parts: Vec<&str> = rest.split('#').collect();
                    if parts.len() >= 4 {
                        colors.insert("urgent_workspace".to_string(), parts[0].to_string());
                    }
                }
            }
        }
    }

    // Extract client colors
    let mut in_client = false;
    for line in config_lines {
        let trimmed = line.trim();

        if trimmed.starts_with("client.") {
            in_client = true;
            continue;
        }

        if in_client {
            if trimmed.starts_with("client.") {
                if let Some(end) = trimmed.find('#') {
                    let rest = trimmed[end..].trim();
                    let parts: Vec<&str> = rest.split('#').collect();
                    if parts.len() >= 4 {
                        let client_type = trimmed.split('#').next().unwrap_or("").to_string();
                        colors.insert(client_type, parts[0].to_string());
                    }
                }
            }
        }
    }

    // Build theme YAML
    let mut yaml = String::from("---\nmeta:\n  description: AUTOMATICALLY GENERATED THEME\n");
    yaml.push_str("colors:\n");

    for (key, value) in &colors {
        yaml.push_str(&format!("  {}: \"{}\"\n", key, value));
    }

    yaml.push_str("window_colors:\n");
    yaml.push_str("  focused:\n");
    yaml.push_str(&format!("    border: {}\n", colors.get("focused").unwrap_or(&"#664477".to_string())));
    yaml.push_str(&format!("    background: {}\n", colors.get("focused").unwrap_or(&"#664477".to_string())));
    yaml.push_str(&format!("    text: {}\n", colors.get("focused").unwrap_or(&"#cccccc".to_string())));
    yaml.push_str(&format!("    indicator: {}\n", colors.get("focused").unwrap_or(&"#e7d8b1".to_string())));

    yaml.push_str("  focused_inactive:\n");
    yaml.push_str(&format!("    border: {}\n", colors.get("focused_inactive").unwrap_or(&"#e7d8b1".to_string())));
    yaml.push_str(&format!("    background: {}\n", colors.get("focused_inactive").unwrap_or(&"#e7d8b1".to_string())));
    yaml.push_str(&format!("    text: {}\n", colors.get("focused_inactive").unwrap_or(&"#181715".to_string())));
    yaml.push_str(&format!("    indicator: {}\n", colors.get("focused_inactive").unwrap_or(&"#A074C4".to_string())));

    yaml.push_str("  unfocused:\n");
    yaml.push_str(&format!("    border: {}\n", colors.get("unfocused").unwrap_or(&"#222133".to_string())));
    yaml.push_str(&format!("    background: {}\n", colors.get("unfocused").unwrap_or(&"#222133".to_string())));
    yaml.push_str(&format!("    text: {}\n", colors.get("unfocused").unwrap_or(&"#AAAAAA".to_string())));
    yaml.push_str(&format!("    indicator: {}\n", colors.get("unfocused").unwrap_or(&"#A074C4".to_string())));

    yaml.push_str("  urgent:\n");
    yaml.push_str(&format!("    border: {}\n", colors.get("urgent").unwrap_or(&"#CE4045".to_string())));
    yaml.push_str(&format!("    background: {}\n", colors.get("urgent").unwrap_or(&"#CE4045".to_string())));
    yaml.push_str(&format!("    text: {}\n", colors.get("urgent").unwrap_or(&"#e7d8b1".to_string())));
    yaml.push_str(&format!("    indicator: {}\n", colors.get("urgent").unwrap_or(&"#DCCD69".to_string())));

    yaml.push_str("bar_colors:\n");
    yaml.push_str(&format!("  background: {}\n", colors.get("background").unwrap_or(&"#222133".to_string())));
    yaml.push_str(&format!("  statusline: {}\n", colors.get("statusline").unwrap_or(&"#FFFFFF".to_string())));
    yaml.push_str(&format!("  separator: {}\n", colors.get("separator").unwrap_or(&"#AAAAAA".to_string())));
    yaml.push_str("  focused_workspace:\n");
    yaml.push_str(&format!("    border: {}\n", colors.get("focused_workspace").unwrap_or(&"#664477".to_string())));
    yaml.push_str(&format!("    background: {}\n", colors.get("focused_workspace").unwrap_or(&"#664477".to_string())));
    yaml.push_str(&format!("    text: {}\n", colors.get("focused_workspace").unwrap_or(&"#cccccc".to_string())));
    yaml.push_str("  urgent_workspace:\n");
    yaml.push_str(&format!("    border: {}\n", colors.get("urgent_workspace").unwrap_or(&"#CE4045".to_string())));
    yaml.push_str(&format!("    background: {}\n", colors.get("urgent_workspace").unwrap_or(&"#CE4045".to_string())));
    yaml.push_str(&format!("    text: {}\n", colors.get("urgent_workspace").unwrap_or(&"#FFFFFF".to_string())));

    yaml
}

fn main() {
    let cli = Cli::parse();

    if cli.list_all {
        println!("\nAvailable themes:\n");
        for theme in get_available_themes() {
            println!("  {}              - {}", theme, get_theme_description(&theme));
        }
        return;
    }

    if cli.to_theme.is_some() {
        let config_path = cli.to_theme.unwrap();
        let config = match fs::read_to_string(&config_path) {
            Ok(content) => content,
            Err(e) => {
                eprintln!("Could not open config: {} - {}", config_path, e);
                process::exit(1);
            }
        };
        let theme_yaml = convert_config_to_theme(&config);
        println!("{}", theme_yaml);
        return;
    }

    let theme_name = match &cli.theme {
        Some(t) => t.clone(),
        None => {
            eprintln!("Select a theme as the first argument. Use `i3-style --list-all` to see the themes.");
            process::exit(1);
        }
    };

    let theme = match load_theme(&theme_name) {
        Ok(t) => t,
        Err(e) => {
            eprintln!("{}", e);
            eprintln!(" Use `i3-style --list-all` to see the available themes.");
            process::exit(1);
        }
    };

    let config_path = cli.config.clone().unwrap_or_else(|| "~/.config/i3/config".to_string());
    let config = match fs::read_to_string(&config_path) {
        Ok(content) => content,
        Err(e) => {
            eprintln!("Could not find i3 config");
            process::exit(1);
        }
    };

    let output_path = if cli.save {
        config_path.clone()
    } else {
        cli.output.clone().unwrap_or_else(|| config_path.clone())
    };

    let output_path_expanded = match fs::canonicalize(&output_path) {
        Ok(path) => path.to_string_lossy().to_string(),
        Err(_) => output_path.clone(),
    };

    let new_config = apply_theme_to_config(&config, &theme);

    // Create temp directory for i3-style
    let temp_dir = format!("/tmp/i3-style/{}", std::process::id());
    fs::create_dir_all(&temp_dir).ok();

    // Save config for validation
    let config_input_path = format!("{}/config-input", temp_dir);
    fs::write(&config_input_path, &config).ok();

    eprintln!("saving config at {} to {}/config-input", config_path, temp_dir);

    // Validate config
    let i3_cmd = "i3 -C -c";
    let validation_output = std::process::Command::new("i3")
        .args(&["-C", "-c", &config_input_path])
        .output();

    if let Ok(output) = validation_output {
        if !output.status.success() {
            let stderr = String::from_utf8_lossy(&output.stderr);
            eprintln!("Could not validate config with `{}` {}", i3_cmd, stderr.trim());
            process::exit(1);
        }
    }

    // Write output
    fs::write(&output_path_expanded, &new_config).ok();

    // Reload if requested
    if cli.reload {
        let reload_output = std::process::Command::new("i3-msg")
            .arg("reload")
            .output();

        if let Ok(output) = reload_output {
            if !output.status.success() {
                let stderr = String::from_utf8_lossy(&output.stderr);
                eprintln!("Could not reload config with i3-msg: {}", stderr.trim());
            }
        }
    }
}
