        let trimmed = line.trim();

        if trimmed.starts_with("bar {") {
            in_bar = true;
            in_colors = false;
            bar_content.push_str(line);
            bar_content.push('\n');
            continue;
        }

        if trimmed == "}" && in_bar {
            in_bar = false;
            bar_content.push_str(line);
            bar_content.push('\n');
            continue;
        }

        if in_bar {
            if trimmed.starts_with("colors {") {
                in_colors = true;
                bar_content.push_str(line);
                bar_content.push('\n');
                continue;
            }

            if trimmed == "}" && in_colors {
                in_colors = false;
                bar_content.push_str(line);
                bar_content.push('\n');
                continue;
            }

            if in_colors {
                bar_content.push_str(line);
